  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '*auth*test*' -g '*config*test*' | head -120",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"rg -n 'allowed_organizations|read:org|redirect_address|client_secret' --glob '*test.go' . | head -180",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"git status --short && ls -la .codex-role-output 2>/dev/null",workdir:"/app",max_output_tokens:1000})
]);
for (let i=0;i<r.length;i++) text(JSON.stringify({idx:i,result:r[i]}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name '*auth*test*' -o -name '*config*test*' | head -160",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"grep -R -n -E 'allowed_organizations|read:org|redirect_address|client_secret' --include='*test.go' . | head -200",workdir:"/app",max_output_tokens:7000}),
  tools.exec_command({cmd:"find . -maxdepth 3 -type f | head -100",workdir:"/app",max_output_tokens:2500})
]);
for (let i=0;i<r.length;i++) text(JSON.stringify({idx:i,result:r[i]}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"sed -n '1,240p' internal/config/config_test.go",workdir:"/app",max_output_tokens:6500}),
  tools.exec_command({cmd:"sed -n '240,560p' internal/config/config_test.go",workdir:"/app",max_output_tokens:9000}),
